"""Stage-3 import converters on real exports: dossiers generated by the frozen stage-1 and
stage-2 services (tests/fixtures; see each file's "source")."""

import json
import pathlib
import unittest
from datetime import date, datetime, timezone

from app.imports import import_stage1, import_stage2
from app.values import values_at

FIXTURES = pathlib.Path(__file__).resolve().parent.parent / "fixtures"
DOMAIN = "acme-robotics.test"
URL = "https://acme-robotics.test/about"


def load(name: str) -> dict:
    return json.loads((FIXTURES / name).read_text(encoding="utf-8"))["dossier"]


class RealStage1ExportTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dossier = load("export_stage1_dossier.json")
        (self.record,) = import_stage1(self.dossier, DOMAIN)

    def test_one_ready_build_at_researched_at_with_its_spending(self) -> None:
        self.assertTrue(self.record.ok)
        self.assertEqual(self.record.index, 1)
        self.assertEqual(self.record.spent_units, 34)
        self.assertEqual(self.record.time, datetime.fromisoformat(self.dossier["researched_at"]))

    def test_one_version_per_cited_url_without_a_true_from(self) -> None:
        self.assertEqual([v.url for v in self.record.versions], [URL])
        self.assertIsNone(self.record.versions[0].true_from)

    def test_values_hold_from_no_date_so_unknown_at_any_date(self) -> None:
        # Stage-1 export records no page dates: a page version with no true_from holds from no date.
        answers = values_at([self.record], date(2026, 6, 1))
        self.assertIsNone(answers["hq_city"].value)


class RealStage2ExportTest(unittest.TestCase):
    def setUp(self) -> None:
        self.dossier = load("export_stage2_dossier.json")
        (self.record,) = import_stage2(self.dossier, DOMAIN)

    def test_one_ready_build_at_researched_at_with_its_spending(self) -> None:
        self.assertTrue(self.record.ok)
        self.assertEqual(self.record.spent_units, 34)
        self.assertEqual(self.record.time, datetime.fromisoformat(self.dossier["researched_at"]))

    def test_true_from_is_the_utc_date_of_published_at_when_no_effective_line(self) -> None:
        version = self.record.versions[0]
        self.assertEqual(version.url, URL)
        self.assertEqual(version.true_from, date(2026, 1, 11))  # 2026-01-10T23:30-05:00 in UTC

    def test_values_at_a_date_after_true_from_give_the_imported_values(self) -> None:
        answers = values_at([self.record], date(2026, 6, 1))
        self.assertEqual(answers["hq_city"].value, "Lisbon")
        self.assertEqual(answers["hq_city"].true_from, date(2026, 1, 11))
        # One page is one version: its candidates share the version's true_from, even the
        # candidate whose export carries no published_at (the page's date is on its other candidate).
        self.assertEqual(answers["ceo"].value, "Dana Ruiz")
        self.assertEqual(answers["ceo"].true_from, date(2026, 1, 11))


if __name__ == "__main__":
    unittest.main()
